{"content": "import csv, re, json, datetime, os

DATA = "/app/data"

def load(name):
    with open(os.path.join(DATA, name), newline="") as f:
        r = csv.reader(f)
        rows = list(r)
    return rows[0], rows[1:]

def is_valid_date(v):
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", v):
        return False
    try:
        datetime.datetime.strptime(v, "%Y-%m-%d")
        return True
    except ValueError:
        return False

def is_number(v):
    try:
        float(v)
        return True
    except (ValueError, TypeError):
        return False

def is_int(v):
    return bool(re.fullmatch(r"-?\d+", v))

email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[a-z]{2,}$")

violations = []
def add(table, row, column, rule):
    violations.append({"table": table, "row": row, "column": column, "rule": rule})

# ---- load ----
cust_h, cust = load("customers.csv")
ord_h, orders = load("orders.csv")
oi_h, order_items = load("order_items.csv")
prod_h, products = load("products.csv")
ref_h, refunds = load("refunds.csv")
ship_h, shipments = load("shipments.csv")

def col(header, name):
    return header.index(name)

# ---- customers ----
c_id = col(cust_h, "id"); c_email = col(cust_h, "email")
c_date = col(cust_h, "signup_date"); c_tier = col(cust_h, "tier")
seen = set()
for i, r in enumerate(cust, start=1):
    # not_null all columns
    for name, idx in [("id", c_id), ("email", c_email), ("signup_date", c_date), ("tier", c_tier)]:
        if r[idx].strip() == "":
            add("customers", i, name, "not_null")
    if r[c_id].strip() != "":
        if r[c_id] in seen:
            add("customers", i, "id", "id")
        else:
            seen.add(r[c_id])
    if r[c_email].strip() != "" and not email_re.fullmatch(r[c_email]):
        add("customers", i, "email", "email")
    if r[c_date].strip() != "" and not is_valid_date(r[c_date]):
        add("customers", i, "signup_date", "date")
    if r[c_tier].strip() != "" and r[c_tier] not in ("free", "pro", "enterprise"):
        add("customers", i, "tier", "enum")

# ---- products ----
p_sku = col(prod_h, "sku"); p_name = col(prod_h, "name")
p_price = col(prod_h, "price"); p_cat = col(prod_h, "category")
seen_sku = set()
for i, r in enumerate(products, start=1):
    for name, idx in [("sku", p_sku), ("name", p_name), ("price", p_price), ("category", p_cat)]:
        if r[idx].strip() == "":
            add("products", i, name, "not_null")
    if r[p_sku].strip() != "":
        if r[p_sku] in seen_sku:
            add("products", i, "sku", "sku")
        else:
            seen_sku.add(r[p_sku])
    if r[p_price].strip() != "":
        if not is_number(r[p_price]):
            add("products", i, "price", "range")
        elif not (float(r[p_price]) > 0):
            add("products", i, "price", "range")

# ---- orders ----
o_id = col(ord_h, "id"); o_cid = col(ord_h, "customer_id")
o_date = col(ord_h, "order_date"); o_status = col(ord_h, "status"); o_total = col(ord_h, "total")

cust_ids = set(r[c_id] for r in cust)
orders_by_id = {r[o_id]: r for r in orders}
seen_oid = set()
for i, r in enumerate(orders, start=1):
    for name, idx in [("id", o_id), ("customer_id", o_cid), ("order_date", o_date), ("status", o_status), ("total", o_total)]:
        if r[idx].strip() == "":
            add("orders", i, name, "not_null")
    if r[o_id].strip() != "":
        if r[o_id] in seen_oid:
            add("orders", i, "id", "id")
        else:
            seen_oid.add(r[o_id])
    if r[o_cid].strip() != "" and r[o_cid] not in cust_ids:
        add("orders", i, "customer_id", "foreign_key")
    if r[o_date].strip() != "" and not is_valid_date(r[o_date]):
        add("orders", i, "order_date", "date")
    if r[o_status].strip() != "" and r[o_status] not in ("placed", "paid", "shipped", "cancelled"):
        add("orders", i, "status", "enum")
    if r[o_total].strip() != "":
        if not is_number(r[o_total]):
            add("orders", i, "total", "range")
        elif not (float(r[o_total]) >= 0):
            add("orders", i, "total", "range")

# ---- order_items ----
i_oid = col(oi_h, "order_id"); i_sku = col(oi_h, "sku")
i_qty = col(oi_h, "qty"); i_price = col(oi_h, "price")
prod_skus = set(r[p_sku] for r in products)
for i, r in enumerate(order_items, start=1):
    for name, idx in [("order_id", i_oid), ("sku", i_sku), ("qty", i_qty), ("price", i_price)]:
        if r[idx].strip() == "":
            add("order_items", i, name, "not_null")
    if r[i_oid].strip() != "" and r[i_oid] not in orders_by_id:
        add("order_items", i, "order_id", "foreign_key")
    if r[i_sku].strip() != "" and r[i_sku] not in prod_skus:
        add("order_items", i, "sku", "foreign_key")
    if r[i_qty].strip() != "":
        if not is_int(r[i_qty]):
            add("order_items", i, "qty", "range")
        elif not (int(r[i_qty]) >= 1):
            add("order_items", i, "qty", "range")
    if r[i_price].strip() != "":
        if not is_number(r[i_price]):
            add("order_items", i, "price", "range")
        elif not (float(r[i_price]) >= 0):
            add("order_items", i, "price", "range")

# ---- refunds ----
r_id = col(ref_h, "id"); r_oid = col(ref_h, "order_id")
r_amt = col(ref_h, "amount"); r_date = col(ref_h, "date")
seen_rid = set()
for i, r in enumerate(refunds, start=1):
    for name, idx in [("id", r_id), ("order_id", r_oid), ("amount", r_amt), ("date", r_date)]:
        if r[idx].strip() == "":
            add("refunds", i, name, "not_null")
    if r[r_id].strip() != "":
        if r[r_id] in seen_rid:
            add("refunds", i, "id", "id")
        else:
            seen_rid.add(r[r_id])
    order = orders_by_id.get(r[r_oid]) if r[r_oid].strip() != "" else None
    if r[r_oid].strip() != "" and order is None:
        add("refunds", i, "order_id", "foreign_key")
    amount_valid = False
    if r[r_amt].strip() != "":
        if is_number(r[r_amt]) and float(r[r_amt]) > 0:
            amount_valid = True
        else:
            add("refunds", i, "amount", "range")
    if r[r_date].strip() != "" and not is_valid_date(r[r_date]):
        add("refunds", i, "date", "date")
    # refund_le_total only if amount passes range and referenced order exists with valid total
    if amount_valid and order is not None and order[o_total].strip() != "" and is_number(order[o_total]) and float(order[o_total]) >= 0:
        if float(r[r_amt]) > float(order[o_total]):
            add("refunds", i, "amount", "refund_le_total")

# ---- shipments ----
s_oid = col(ship_h, "order_id"); s_carrier = col(ship_h, "carrier"); s_date = col(ship_h, "shipped_date")
for i, r in enumerate(shipments, start=1):
    for name, idx in [("order_id", s_oid), ("carrier", s_carrier), ("shipped_date", s_date)]:
        if r[idx].strip() == "":
            add("shipments", i, name, "not_null")
    order = orders_by_id.get(r[s_oid]) if r[s_oid].strip() != "" else None
    if r[s_oid].strip() != "" and order is None:
        add("shipments", i, "order_id", "foreign_key")
    if r[s_carrier].strip() != "" and r[s_carrier] not in ("ups", "dhl", "fedex"):
        add("shipments", i, "carrier", "enum")
    date_valid = False
    if r[s_date].strip() != "":
        if is_valid_date(r[s_date]):
            date_valid = True
        else:
            add("shipments", i, "shipped_date", "date")
    if date_valid and order is not None and order[o_date].strip() != "" and is_valid_date(order[o_date]):
        if datetime.date.fromisoformat(r[s_date]) < datetime.date.fromisoformat(order[o_date]):
            add("shipments", i, "shipped_date", "ship_after_order")

violations.sort(key=lambda v: (v["table"], v["row"], v["column"], v["rule"]))

os.makedirs("/app/out", exist_ok=True)
with open("/app/out/dq-report.json", "w") as f:
    json.dump(violations, f, indent=2)

print(json.dumps(violations, indent=2))
print("TOTAL", len(violations))
